class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        # Edge case: if the input list is empty, return an empty string
        if not strs:
            return ""

        # Initialize the common prefix with the first string in the list
        common_prefix = strs[0]

        # Iterate over the rest of the strings in the list
        for s in strs[1:]:
            # Update the common prefix by comparing characters at each position
            while not s.startswith(common_prefix):
                common_prefix = common_prefix[:-1]
                if not common_prefix:
                    return ""

