def is_simple_power(x, n):
    # If x is 1, it is a simple power of any n (since n^0 = 1 for any n)
    if x == 1:
        return True

    # If x or n is 0, they cannot be a simple power of each other
    if x == 0 or n == 0:
        return False

    # Check if there exists an integer exponent such that n^exponent == x
    while x >= n:
        if x % n == 0:
            x //= n
        else:
            break
    return x == 1

