    # Ensure a is less than or equal to b for iteration
    if a > b:
        a, b = b, a

    even_digits = []

    # Iterate through the range from a to b
    for num in range(a, b + 1):
        # Convert the number to a string to check each digit
        for digit in str(num):
            # Check if the digit is an even number
            if int(digit) % 2 == 0:
                even_digits.append(int(digit))
                break  # No
